import { slardar } from "@lark-apaas/internal-slardar";
class PermissionClient {
    constructor(config){
        this.config = config;
    }
    async fetchPermissions() {
        const { url, timeout = 5000, headers = {} } = this.config;
        const requestHeaders = {
            ...headers,
            'Content-Type': 'application/json',
            'X-Suda-Csrf-Token': window.csrfToken || ''
        };
        const controller = new AbortController();
        const timeoutId = setTimeout(()=>controller.abort(), timeout);
        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: requestHeaders,
                signal: controller.signal,
                credentials: 'include'
            });
            clearTimeout(timeoutId);
            if (!response.ok) throw new Error(`Permission API returned ${response.status}: ${response.statusText}`);
            const data = await response.json();
            return {
                roles: data.data?.roleList || [],
                fetchedAt: new Date()
            };
        } catch (error) {
            clearTimeout(timeoutId);
            if (error instanceof Error && 'AbortError' === error.name) {
                slardar.captureException(error, {
                    source: 'auth-sdk',
                    type: 'timeout'
                });
                throw new Error(`Permission API request timeout after ${timeout}ms`);
            }
            slardar.captureException(error, {
                source: 'auth-sdk',
                type: 'fetch'
            });
            throw error;
        }
    }
    static async fetchPermissionPoints() {
        const appId = window.appId || '';
        const url = `/app/${appId}/api/sdk_innerapi/permission/user-points`;
        const controller = new AbortController();
        const timeoutId = setTimeout(()=>controller.abort(), 5000);
        try {
            const response = await fetch(url, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Suda-Csrf-Token': window.csrfToken || ''
                },
                signal: controller.signal,
                credentials: 'include'
            });
            clearTimeout(timeoutId);
            if (!response.ok) throw new Error(`Permission Points API returned ${response.status}: ${response.statusText}`);
            return await response.json();
        } catch (error) {
            clearTimeout(timeoutId);
            if (error instanceof Error && 'AbortError' === error.name) {
                slardar.captureException(error, {
                    source: 'auth-sdk',
                    type: 'timeout'
                });
                throw new Error('Permission Points API request timeout');
            }
            slardar.captureException(error, {
                source: 'auth-sdk',
                type: 'fetch'
            });
            throw error;
        }
    }
    updateConfig(config) {
        this.config = {
            ...this.config,
            ...config
        };
    }
    getConfig() {
        return {
            ...this.config
        };
    }
}
export { PermissionClient };
